const { resolveRequestedTagIds } = require('./resolveRequestedTagIds');

function buildQueryString(config) {
  const params = new URLSearchParams();
  const tagIds = resolveRequestedTagIds(config);

  if (tagIds.length > 0) {
    params.append('requestedTagIds', JSON.stringify(tagIds));
  }

  if (config.queryParams) {
    Object.entries(config.queryParams).forEach(([key, value]) => {
      if (key !== 'requestedTagIds') {
        params.append(key, value);
      }
    });
  }

  return params.toString();
}

module.exports = { buildQueryString };
